// Assemble declarations from the pinned upstream baseline, binding metadata,
// explicit manual contracts, and checked JavaScript. Generated files are never edited.
const fs = require("fs");
const path = require("path");
const ts = require("typescript");
const generateJson = require("./generateJson");
const config = require("../input/typings.json");
const root = path.resolve(__dirname, "../..");
const baseline = path.dirname(require.resolve("@types/nodegit/package.json"));
const banner = "// Generated by npm run generate:types. Do not edit.\n";
const printer = ts.createPrinter();

function parse(text) {
  return ts.createSourceFile("types.d.ts", text, ts.ScriptTarget.Latest, true);
}

function applyEdits(text, edits) {
  return edits.sort((a, b) => b.start - a.start).reduce((value, edit) =>
    value.slice(0, edit.start) + edit.text + value.slice(edit.end), text);
}

function generateTypes() {
  generateJson();
  const definitions = JSON.parse(fs.readFileSync(path.join(root, "generate/output/idefs.json")));
  if (require(path.join(baseline, "package.json")).version !== "0.28.9") throw new Error("Unexpected upstream declaration version");
  const classes = new Map(definitions.filter(d => d.type !== "enum").map(d => [d.cppClassName, d]));
  const constants = new Map();
  for (const definition of definitions.filter(d => d.type === "enum" && !d.ignore)) {
    constants.set(definition.owner + "." + definition.JsName, {
      mask: definition.isMask,
      values: Object.fromEntries(definition.values.map(v => [v.JsName, v.value]))
    });
  }
  function constantValue(value) {
    if (typeof value === "number") return value;
    const parts = value.split(".");
    const original = constants.get(parts.slice(0, 2).join("."))?.values[parts[2]];
    if (typeof original !== "number") throw new Error("Unknown constant " + value);
    return original;
  }
  for (const [name, members] of Object.entries(config.constantMembers)) {
    Object.assign(constants.get(name).values, Object.fromEntries(
      Object.entries(members).map(([key, value]) => [key, constantValue(value)])));
  }
  for (const [name, alias] of Object.entries(config.constantAliases)) {
    let values;
    if (typeof alias === "string") {
      if (!constants.has(alias)) throw new Error("Unknown constant alias " + alias);
      values = constants.get(alias).values;
    } else {
      values = Object.fromEntries(Object.entries(alias).map(([key, value]) => {
        return [key, constantValue(value)];
      }));
    }
    constants.set(name, { mask: true, values });
  }

  function typeOf(value, input = false) {
    const primitive = { Number: "number", Integer: "number", Uint32: "number", Int32: "number", Bool: "boolean", Boolean: "boolean", String: "string", Buffer: "Buffer", Void: "void", GitBuf: input ? "Buffer | string" : "string", GitStrarray: "string[]" };
    if (value.isNullable) return typeOf({ ...value, isNullable: false }, input) + " | null";
    if (primitive[value.cppClassName]) return primitive[value.cppClassName];
    if (value.cppClassName === "Array") {
      return value.arrayElementCppClassName ? "(" + typeOf({ cppClassName: value.arrayElementCppClassName }, input) + ")[]" : "string[]";
    }
    const definition = classes.get(value.cppClassName);
    if (!definition) throw new Error("Missing type mapping for " + value.cppClassName);
    let result = "Git." + definition.jsClassName;
    if (input && definition.jsClassName === "Oid") result += " | string";
    return result;
  }

  function signature(fn) {
    if (fn.isManual) throw new Error("Manual native method needs an explicit contract: " + fn.jsFunctionName);
    const inputs = fn.args.filter(a => !a.isSelf && !a.isReturn && !a.ignore);
    const args = inputs.map((arg, index) => {
      const optional = arg.isOptional && inputs.slice(index).every(a => a.isOptional);
      let type = typeOf(arg, true);
      if (arg.isOptional) type += " | null" + (optional ? "" : " | undefined");
      return arg.name + (optional ? "?" : "") + ": " + type;
    }).join(", ");
    let outputs = fn.args.filter(a => a.isReturn);
    if (!outputs.length && fn.return && !fn.return.isErrorCode && fn.return.cType !== "void") outputs = [fn.return];
    let result = "void";
    if (fn.return?.isResultOrError) result = "number";
    else if (outputs.length === 1) result = typeOf(outputs[0]);
    else if (outputs.length > 1) result = "{ " + outputs.map(a => (a.returnName || a.name) + ": " + typeOf(a)).join("; ") + " }";
    // The synchronous binding template returns undefined for a null C pointer.
    if (!fn.isAsync && outputs[0] === fn.return && /\*/.test(fn.return.cType)) result += " | undefined";
    if (fn.isAsync) result = "Promise<" + result + ">";
    return (fn.isPrototypeMethod ? "" : "static ") + fn.jsFunctionName + "(" + args + "): " + result + ";";
  }

  const manualMethods = {};
  for (const file of config.manualSources) {
    const source = fs.readFileSync(path.join(root, file), "utf8");
    for (const match of source.matchAll(/@nodegit-type (\w+)([.#])(\w+)([^\n]+)/g)) {
      const [, owner, separator, name, contract] = match;
      manualMethods[owner] ||= {};
      if (manualMethods[owner][name]) throw new Error("Duplicate manual contract " + owner + "." + name);
      manualMethods[owner][name] = (separator === "." ? "static " : "") + name + contract;
    }
  }
  const methods = new Map();
  const native = [];
  for (const [name, selected] of Object.entries(config.nativeMethods)) {
    const definition = definitions.find(d => d.jsClassName === name);
    if (!definition) throw new Error("Unknown native class " + name);
    if (selected !== "*") {
      for (const name of selected) {
        if (!definition.functions.some(fn => fn.jsFunctionName === name)) throw new Error("Unknown native method " + name);
      }
    }
    const generated = new Map();
    for (const fn of definition.functions) {
      if (selected !== "*" && !selected.includes(fn.jsFunctionName)) continue;
      if (fn.isManual) {
        if (!manualMethods[name]?.[fn.jsFunctionName]) throw new Error("Missing manual contract " + name + "." + fn.jsFunctionName);
        continue;
      }
      generated.set(fn.jsFunctionName, signature(fn));
    }
    for (const [method, contract] of Object.entries(manualMethods[name] || {})) generated.set(method, contract);
    methods.set(name, generated);
    native.push("export declare class " + name + " {\n" + [...generated.values()].map(s => "  " + s).join("\n") + "\n}");
  }
  for (const [name, contracts] of Object.entries(manualMethods)) {
    if (!methods.has(name)) methods.set(name, new Map(Object.entries(contracts)));
  }
  for (const name of config.nativeFields) {
    const definition = definitions.find(d => d.jsClassName === name);
    methods.set(name, new Map(definition.fields.map(field =>
      [field.jsFunctionName, field.jsFunctionName + "(): " + typeOf(field) + ";"])));
  }
  const output = path.join(root, "types");
  fs.rmSync(output, { recursive: true, force: true });
  fs.mkdirSync(output, { recursive: true });
  fs.writeFileSync(path.join(output, "native.d.ts"), banner + 'import * as Git from "./index";\n' + native.join("\n"));
  const files = new Map();
  const owners = new Map();
  const sources = new Map();
  for (const file of fs.readdirSync(baseline).filter(file => file.endsWith(".d.ts")).sort()) {
    const source = parse(fs.readFileSync(path.join(baseline, file), "utf8"));
    sources.set(file, source);
    for (const node of source.statements) {
      if ((ts.isClassDeclaration(node) || ts.isModuleDeclaration(node)) && node.name) owners.set(node.name.text, file);
    }
  }
  for (const name of methods.keys()) {
    if (owners.has(name)) continue;
    const definition = definitions.find(d => d.jsClassName === name);
    const file = definition.filename.replace(/_/g, "-") + ".d.ts";
    sources.set(file, parse("export class " + name + " {}\n"));
    owners.set(name, file);
  }

  for (const [file, source] of sources) {
    const edits = [];
    function visit(node) {
      if (ts.isEnumDeclaration(node)) {
        edits.push({ start: node.getFullStart(), end: node.end, text: "" });
        return;
      }
      if (ts.isClassDeclaration(node) && methods.has(node.name.text)) {
        const replacements = new Map([...methods.get(node.name.text)].filter(([name]) =>
          !config.javascriptMethods[node.name.text]?.[name]));
        for (const member of node.members) {
          if (member.name && replacements.has(member.name.getText(source))) edits.push({ start: member.getFullStart(), end: member.end, text: "" });
        }
        edits.push({ start: node.end - 1, end: node.end - 1, text: "\n" + [...replacements.values()].map(s => "  " + s).join("\n") + "\n" });
      }
      ts.forEachChild(node, visit);
    }
    visit(source);
    let text = applyEdits(source.text, edits);
    if ([...methods.keys()].some(name => owners.get(name) === file)) text = 'import * as Git from "./index";\n' + text;
    files.set(file, text);
  }
  for (const [key, group] of constants) {
    const [owner, name] = key.split(".");
    const file = owners.get(owner) || "constants.d.ts";
    const entries = Object.entries(group.values).map(([key, value]) => "readonly " + JSON.stringify(key) + ": " + value + ";").join("\n");
    const declaration = "\nexport namespace " + owner + " {\nexport const " + name + ": {\n" + entries + "\n};\nexport type " + name + " = " + (group.mask ? "number" : "typeof " + name + "[keyof typeof " + name + "]") + ";\n}\n";
    // Keep enum-member type spellings (Diff.FORMAT.PATCH) without emitting enums.
    const members = Object.keys(group.values).map(key =>
      "export type " + key + " = typeof " + owner + "." + name + "." + key + ";").join("\n");
    files.set(file, (files.get(file) || "") + declaration +
      "export namespace " + owner + "." + name + " {\n" + members + "\n}\n");
  }
  if (files.has("constants.d.ts")) files.set("index.d.ts", files.get("index.d.ts") + '\nexport * from "./constants";\n');
  files.set("index.d.ts", files.get("index.d.ts") + '\nexport { Patch } from "./patch";\nexport { DiffHunk } from "./diff-hunk";\n');

  function writeFiles() {
    for (const [file, text] of files) {
      fs.writeFileSync(path.join(output, file), banner + printer.printFile(parse(text)));
    }
  }
  writeFiles();
  // Bootstrap public declarations above before checking the JavaScript that imports them.
  const configPath = path.join(root, "tsconfig.types.json");
  const parsed = ts.getParsedCommandLineOfConfigFile(configPath, {}, ts.sys);
  const program = ts.createProgram(parsed.fileNames, parsed.options);
  // Emit explicit JSDoc contracts first to break the bootstrap cycle: convenience
  // implementations import public types, and public types refer to these helpers.
  program.emit(undefined, (file, text) => {
    // JSDoc imports are relative to lib/. Rebase them for types/js/.
    text = text.replace(/(["'])\.\.\/types\1/g, '"../index"');
    const destination = path.join(output, "js", path.relative(parsed.options.outDir, file));
    fs.mkdirSync(path.dirname(destination), { recursive: true });
    fs.writeFileSync(destination, banner + text);
  });
  for (const [owner, members] of Object.entries(config.javascriptMethods)) {
    const file = owners.get(owner);
    let source = parse(files.get(file));
    const edits = [];
    for (const node of source.statements.filter(ts.isClassDeclaration)) {
      if (node.name.text !== owner) continue;
      const remaining = new Set(Object.keys(members));
      for (const member of node.members) {
        const name = member.name?.getText(source);
        if (members[name]) {
          edits.push({ start: member.getFullStart(), end: member.end, text: '\nstatic ' + name + ': typeof import("./js/' + members[name] + '").' + name + ';\n' });
          remaining.delete(name);
        }
      }
      edits.push({ start: node.end - 1, end: node.end - 1, text: [...remaining].map(name => '\nstatic ' + name + ': typeof import("./js/' + members[name] + '").' + name + ';\n').join("") });
    }
    files.set(file, applyEdits(source.text, edits));
  }
  writeFiles();
  const checked = ts.createProgram(parsed.fileNames, { ...parsed.options, noEmit: true, emitDeclarationOnly: false });
  const diagnostics = ts.getPreEmitDiagnostics(checked);
  if (diagnostics.length) throw new Error(ts.formatDiagnosticsWithColorAndContext(diagnostics, {
    getCurrentDirectory: () => root, getCanonicalFileName: f => f, getNewLine: () => "\n"
  }));
  fs.copyFileSync(path.join(baseline, "LICENSE"), path.join(output, "LICENSE"));
  fs.writeFileSync(path.join(output, "NOTICE"), "Derived from @types/nodegit 0.28.9 (DefinitelyTyped), MIT licensed.\nhttps://github.com/DefinitelyTyped/DefinitelyTyped/tree/master/types/nodegit\nGenerated binding contracts and Jabali modifications are maintained in this repository.\n");
  console.log("Generated bundled declarations (baseline @types/nodegit 0.28.9).");
}

module.exports = generateTypes;
if (require.main === module) generateTypes();
